// The ZYGAL logo, embedded directly so the app stays one self-contained build
// with no separate image file to host or go missing.
export const LOGO_MARK = 'data:image/png;base64,'
export const LOGO_FULL = 'data:image/png;base64,'

export function LogoMark({ size = 36 }: { size?: number }) {
  return <img src={LOGO_MARK} alt="ZYGAL" width={size} height={size * 1.27} className="logo-mark" />
}

export function LogoFull({ width = 160 }: { width?: number }) {
  return <img src={LOGO_FULL} alt="ZYGAL — Connecting Structures" width={width} className="logo-full" />
}
